1	"use client";
2	
3	import { useState } from "react";
4	import { GamePlayers } from "./GamePlayers";
5	import { GameInventory } from "./GameInventory";
6	import { GameRoles } from "./GameRoles";
7	
8	type SubTabDef = { key: string; label: string; mc?: boolean };
9	
10	const SUB_TABS: SubTabDef[] = [
11	  { key: "online", label: "Online Players" },
12	  { key: "inventory", label: "Inventory", mc: true },
13	  { key: "roles", label: "Roles & Permissions", mc: true },
14	];
15	
16	type SubKey = "online" | "inventory" | "roles";
17	
18	export function GamePlayersHub({
19	  serverId,
20	  running,
21	  playersMax,
22	  isMc,
23	}: {
24	  serverId: string;
25	  running: boolean;
26	  playersMax: number | null;
27	  isMc: boolean;
28	}) {
29	  const [sub, setSub] = useState<SubKey>("online");
30	  const visible = SUB_TABS.filter((t) => !t.mc || isMc);
31	
32	  return (
33	    <div className="flex flex-col gap-3">
34	      {/* Sub-tab pills, matching every other sub-tab bar in the panel — only
35	          drawn when there is more than one tab to choose between. */}
36	      {visible.length > 1 && (
37	        <div className="flex w-fit gap-1 rounded-[11px] border border-rim-hi bg-[rgba(6,14,36,.72)] p-1">
38	          {visible.map((t) => {
39	            const active = sub === t.key;
40	            return (
41	              <button
42	                key={t.key}
43	                type="button"
44	                onClick={() => setSub(t.key as SubKey)}
45	                aria-pressed={active}
46	                className={
47	                  "rounded-[8px] px-3.5 py-1.5 text-[12.5px] font-semibold transition " +
48	                  (active ? "bg-[#7b3fef]/25 text-white" : "text-tx-dim hover:text-white")
49	                }
50	              >
51	                {t.label}
52	              </button>
53	            );
54	          })}
55	        </div>
56	      )}
57	
58	      {sub === "online" && (
59	        <GamePlayers serverId={serverId} running={running} playersMax={playersMax} />
60	      )}
61	      {sub === "inventory" && isMc && (
62	        <GameInventory serverId={serverId} running={running} />
63	      )}
64	      {sub === "roles" && isMc && (
65	        <GameRoles serverId={serverId} running={running} />
66	      )}
67	    </div>
68	  );
69	}
