1	"use client";
2	
3	import { useCallback, useEffect, useState, useTransition } from "react";
4	import {
5	  getPlayerHistory,
6	  getPlayerStats,
7	  type PlayerSessionRow,
8	  type PlayerStatsResult,
9	} from "@/lib/actions-game-control";
10	
11	function formatDuration(ms: number): string {
12	  if (ms < 60_000) return "< 1m";
13	  const totalMin = Math.floor(ms / 60_000);
14	  const h = Math.floor(totalMin / 60);
15	  const m = totalMin % 60;
16	  if (h > 0) return m > 0 ? `${h}h ${m}m` : `${h}h`;
17	  return `${m}m`;
18	}
19	
20	function formatDurationLong(ms: number): string {
21	  const totalMin = Math.floor(ms / 60_000);
22	  const h = Math.floor(totalMin / 60);
23	  const m = totalMin % 60;
24	  if (h > 0) return m > 0 ? `${h}h ${m}m` : `${h}h`;
25	  if (m > 0) return `${m}m`;
26	  return "< 1m";
27	}
28	
29	function relativeTime(iso: string): string {
30	  const diff = Date.now() - new Date(iso).getTime();
31	  if (diff < 60_000) return "just now";
32	  const min = Math.floor(diff / 60_000);
33	  if (min < 60) return `${min}m ago`;
34	  const hr = Math.floor(min / 60);
35	  if (hr < 24) return `${hr}h ago`;
36	  const d = Math.floor(hr / 24);
37	  return `${d}d ago`;
38	}
39	
40	export function GamePlayerHistory({ serverId }: { serverId: string }) {
41	  const [stats, setStats] = useState<Extract<PlayerStatsResult, { ok: true }> | null>(null);
42	  const [sessions, setSessions] = useState<PlayerSessionRow[]>([]);
43	  const [total, setTotal] = useState(0);
44	  const [search, setSearch] = useState("");
45	  const [appliedSearch, setAppliedSearch] = useState("");
46	  const [offset, setOffset] = useState(0);
47	  const [err, setErr] = useState<string | null>(null);
48	  const [pending, start] = useTransition();
49	
50	  const PAGE_SIZE = 100;
51	
52	  const loadStats = useCallback(() => {
53	    start(async () => {
54	      const r = await getPlayerStats(serverId);
55	      if (r.ok) setStats(r);
56	      else setErr(r.error);
57	    });
58	  }, [serverId]);
59	
60	  const loadHistory = useCallback(
61	    (searchVal: string, off: number) => {
62	      start(async () => {
63	        const r = await getPlayerHistory(serverId, {
64	          limit: PAGE_SIZE,
65	          offset: off,
66	          playerName: searchVal || undefined,
67	        });
68	        if (r.ok) {
69	          setSessions(off === 0 ? r.sessions : (prev) => [...prev, ...r.sessions]);
70	          setTotal(r.total);
71	          setErr(null);
72	        } else {
73	          setErr(r.error);
74	        }
75	      });
76	    },
77	    [serverId]
78	  );
79	
80	  useEffect(() => {
81	    loadStats();
82	    loadHistory("", 0);
83	  }, [loadStats, loadHistory]);
84	
85	  function doSearch() {
86	    const val = search.trim();
87	    setAppliedSearch(val);
88	    setOffset(0);
89	    setSessions([]);
90	    loadHistory(val, 0);
91	  }
92	
93	  function loadMore() {
94	    const newOffset = offset + PAGE_SIZE;
95	    setOffset(newOffset);
96	    loadHistory(appliedSearch, newOffset);
97	  }
98	
99	  return (
100	    <div className="space-y-5">
101	      {/* Stats overview */}
102	      {stats && (
103	        <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
104	          <StatCard label="Unique players" value={String(stats.uniquePlayers)} />
105	          <StatCard label="Online now" value={String(stats.currentOnline)} highlight />
106	          <StatCard label="Total playtime" value={formatDurationLong(stats.totalPlaytimeMs)} />
107	          <StatCard label="Avg session" value={stats.avgSessionMs > 0 ? formatDurationLong(stats.avgSessionMs) : "--"} />
108	        </div>
109	      )}
110	
111	      {/* Top players */}
112	      {stats && stats.topPlayers.length > 0 && (
113	        <div className="card">
114	          <h3 className="font-semibold">Top players</h3>
115	          <p className="mt-0.5 text-sm text-slate-400">By total playtime</p>
116	          <ul className="mt-4 divide-y divide-white/[0.06]">
117	            {stats.topPlayers.map((p, i) => (
118	              <li key={p.name} className="flex items-center justify-between gap-3 py-2.5">
119	                <span className="flex items-center gap-2.5 text-sm">
120	                  <span className="flex h-8 w-8 items-center justify-center rounded-full bg-gradient-to-br from-brand-500/40 to-accent-blue/30 text-[11px] font-bold text-white">
121	                    {i + 1}
122	                  </span>
123	                  <span className="font-medium text-slate-100">{p.name}</span>
124	                </span>
125	                <span className="text-sm text-slate-400">
126	                  {formatDurationLong(p.totalMs)} · {p.sessions} session{p.sessions !== 1 ? "s" : ""}
127	                </span>
128	              </li>
129	            ))}
130	          </ul>
131	        </div>
132	      )}
133	
134	      {/* Session log */}
135	      <div className="card">
136	        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
137	          <div>
138	            <h3 className="font-semibold">Session log</h3>
139	            <p className="mt-0.5 text-sm text-slate-400">{total} session{total !== 1 ? "s" : ""} recorded</p>
140	          </div>
141	          <div className="flex gap-2">
142	            <input
143	              className="input w-48"
144	              placeholder="Filter by player..."
145	              value={search}
146	              onChange={(e) => setSearch(e.target.value)}
147	              onKeyDown={(e) => e.key === "Enter" && doSearch()}
148	            />
149	            <button
150	              className="btn-primary text-sm"
151	              onClick={doSearch}
152	              disabled={pending}
153	            >
154	              Search
155	            </button>
156	          </div>
157	        </div>
158	
159	        {err && <p className="mt-3 text-sm text-amber-300">{err}</p>}
160	
161	        {sessions.length === 0 && !pending && !err ? (
162	          <p className="mt-4 text-sm text-slate-500">
163	            {appliedSearch ? "No sessions found for this player." : "No player sessions recorded yet. Sessions are tracked automatically while the server is running."}
164	          </p>
165	        ) : (
166	          <>
167	            {/* Table header - desktop */}
168	            <div className="mt-4 hidden text-xs font-medium uppercase tracking-wide text-slate-500 sm:grid sm:grid-cols-[1fr_1fr_1fr_auto]">
169	              <span>Player</span>
170	              <span>Joined</span>
171	              <span>Left</span>
172	              <span className="text-right">Duration</span>
173	            </div>
174	
175	            <ul className="mt-2 divide-y divide-white/[0.06] sm:mt-1">
176	              {sessions.map((s) => {
177	                const isOnline = !s.leftAt;
178	                const duration = s.durationMs
179	                  ? formatDuration(s.durationMs)
180	                  : isOnline
181	                  ? formatDuration(Date.now() - new Date(s.joinedAt).getTime())
182	                  : "--";
183	
184	                return (
185	                  <li key={s.id} className="py-2.5 sm:grid sm:grid-cols-[1fr_1fr_1fr_auto] sm:items-center">
186	                    {/* Player name */}
187	                    <span className="flex items-center gap-2.5 text-sm">
188	                      <span className="flex h-8 w-8 items-center justify-center rounded-full bg-gradient-to-br from-brand-500/40 to-accent-blue/30 text-[11px] font-bold text-white">
189	                        {s.playerName.slice(0, 2).toUpperCase()}
190	                      </span>
191	                      <span className="font-medium text-slate-100">{s.playerName}</span>
192	                      {isOnline && (
193	                        <span className="flex items-center gap-1 rounded-full bg-emerald-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-emerald-400">
194	                          <span className="h-2 w-2 rounded-full bg-emerald-400" />
195	                          Online
196	                        </span>
197	                      )}
198	                    </span>
199	
200	                    {/* Joined */}
201	                    <span className="mt-1 block text-sm text-slate-400 sm:mt-0">
202	                      <span className="text-slate-500 sm:hidden">Joined </span>
203	                      {relativeTime(s.joinedAt)}
204	                    </span>
205	
206	                    {/* Left */}
207	                    <span className="mt-0.5 block text-sm text-slate-400 sm:mt-0">
208	                      {isOnline ? (
209	                        <span className="text-emerald-400">Online now</span>
210	                      ) : (
211	                        <>
212	                          <span className="text-slate-500 sm:hidden">Left </span>
213	                          {relativeTime(s.leftAt!)}
214	                        </>
215	                      )}
216	                    </span>
217	
218	                    {/* Duration */}
219	                    <span className="mt-0.5 block text-right text-sm text-slate-400 sm:mt-0">
220	                      <span className="text-slate-500 sm:hidden">Duration: </span>
221	                      {duration}
222	                    </span>
223	                  </li>
224	                );
225	              })}
226	            </ul>
227	
228	            {sessions.length < total && (
229	              <div className="mt-4 text-center">
230	                <button
231	                  className="text-sm text-slate-400 hover:text-white disabled:opacity-40"
232	                  onClick={loadMore}
233	                  disabled={pending}
234	                >
235	                  {pending ? "Loading..." : `Load more (${total - sessions.length} remaining)`}
236	                </button>
237	              </div>
238	            )}
239	          </>
240	        )}
241	      </div>
242	    </div>
243	  );
244	}
245	
246	function StatCard({ label, value, highlight }: { label: string; value: string; highlight?: boolean }) {
247	  return (
248	    <div className="card flex flex-col items-center justify-center py-4 text-center">
249	      <p className={`text-2xl font-bold ${highlight ? "text-emerald-400" : "text-white"}`}>{value}</p>
250	      <p className="mt-1 text-xs text-slate-400">{label}</p>
251	    </div>
252	  );
253	}
