1	"use client";
2	
3	import { useMemo, useState } from "react";
4	import { Icon } from "@/components/nx/Icon";
5	
6	/**
7	 * Everything the platform has done to this server.
8	 *
9	 * The tab showed the last twenty Job rows, unfiltered and unpaginated, so a
10	 * server with any history at all simply lost the older half. It is the same
11	 * source — `Job` is the only server-scoped record there is, since `AuditLog`
12	 * carries a userId and an action string but no serverId — with a wider window,
13	 * a filter and paging over it.
14	 */
15	
16	export type ActivityRow = {
17	  id: string;
18	  type: string;
19	  status: string;
20	  createdAt: string;
21	  finishedAt: string | null;
22	  error: string | null;
23	};
24	
25	const PER_PAGE = 15;
26	
27	const STATUS: Record<string, { label: string; dot: string; ink: string }> = {
28	  QUEUED:  { label: "Queued",  dot: "bg-slate-400",             ink: "text-tx-dim" },
29	  RUNNING: { label: "Running", dot: "bg-[#c4a6ff] animate-pulse", ink: "text-[#c4a6ff]" },
30	  DONE:    { label: "Done",    dot: "bg-emerald-400",           ink: "text-emerald-400" },
31	  FAILED:  { label: "Failed",  dot: "bg-red-400",               ink: "text-red-400" },
32	};
33	
34	/* The job types a customer can actually be shown, in words rather than the
35	   worker's enum. Anything unmapped falls back to the raw type rather than
36	   being hidden — an unknown job still happened to their server. */
37	const TYPE_LABEL: Record<string, { label: string; icon: string }> = {
38	  PROVISION:      { label: "Server created",        icon: "cube" },
39	  REINSTALL:      { label: "Reinstalled",           icon: "refresh" },
40	  DELETE:         { label: "Deleted",               icon: "trash" },
41	  RESIZE:         { label: "Plan changed",          icon: "bolt" },
42	  START:          { label: "Started",               icon: "bolt" },
43	  STOP:           { label: "Stopped",               icon: "xcircle" },
44	  REBOOT:         { label: "Rebooted",              icon: "refresh" },
45	  BACKUP_CREATE:  { label: "Backup created",        icon: "archive" },
46	  BACKUP_RESTORE: { label: "Backup restored",       icon: "archive" },
47	  GAME_POWER:     { label: "Game service power",    icon: "gamepad" },
48	  GAME_CONFIG:    { label: "Settings applied",      icon: "gear" },
49	  GAME_MOD_SYNC:  { label: "Mods synced",           icon: "cube" },
50	  GAME_BACKUP:    { label: "World archived",        icon: "database" },
51	  GAME_UPDATE:    { label: "Game updated",          icon: "download" },
52	  MIGRATE:        { label: "Migration",             icon: "transfer2" },
53	  SSL_ISSUE:      { label: "Certificate issued",    icon: "lock2" },
54	};
55	
56	function when(iso: string): string {
57	  return new Date(iso).toLocaleString("en-US", {
58	    year: "numeric", month: "short", day: "numeric", hour: "2-digit", minute: "2-digit",
59	  });
60	}
61	
62	function took(a: string, b: string | null): string | null {
63	  if (!b) return null;
64	  const s = Math.round((new Date(b).getTime() - new Date(a).getTime()) / 1000);
65	  if (s < 0) return null;
66	  if (s < 60) return `${s}s`;
67	  if (s < 3600) return `${Math.floor(s / 60)}m ${s % 60}s`;
68	  return `${Math.floor(s / 3600)}h ${Math.floor((s % 3600) / 60)}m`;
69	}
70	
71	export function GameActivityPanel({ rows }: { rows: ActivityRow[] }) {
72	  const [status, setStatus] = useState<"all" | "DONE" | "FAILED" | "RUNNING">("all");
73	  const [page, setPage] = useState(1);
74	
75	  const shown = useMemo(() => {
76	    const f = rows.filter((r) => status === "all" || r.status === status);
77	    return f;
78	  }, [rows, status]);
79	
80	  const pages = Math.max(1, Math.ceil(shown.length / PER_PAGE));
81	  const current = Math.min(page, pages);
82	  const slice = shown.slice((current - 1) * PER_PAGE, current * PER_PAGE);
83	
84	  const counts = useMemo(() => ({
85	    all: rows.length,
86	    DONE: rows.filter((r) => r.status === "DONE").length,
87	    FAILED: rows.filter((r) => r.status === "FAILED").length,
88	    RUNNING: rows.filter((r) => r.status === "RUNNING" || r.status === "QUEUED").length,
89	  }), [rows]);
90	
91	  return (
92	    <section className="flex min-w-0 flex-col rounded-[16px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.5),rgba(2,7,20,.62))]">
93	      <div className="flex flex-wrap items-center gap-2.5 border-b border-rim-soft px-4 py-3">
94	        <h3 className="text-[14px] font-extrabold text-white">Activity</h3>
95	        <span className="text-[12px] text-tx-faint">everything we&apos;ve done to this server</span>
96	        <span className="ml-auto flex gap-1 rounded-[10px] border border-rim-hi bg-[rgba(6,14,36,.72)] p-1">
97	          {([["all", "All"], ["DONE", "Done"], ["FAILED", "Failed"], ["RUNNING", "In flight"]] as const).map(([k, label]) => (
98	            <button key={k} type="button" onClick={() => { setStatus(k); setPage(1); }} aria-pressed={status === k}
99	                    className={"rounded-[7px] px-3 py-1 text-[12px] font-semibold transition " +
100	                      (status === k ? "bg-[#7b3fef]/25 text-white" : "text-tx-dim hover:text-white")}>
101	              {label} <span className="text-tx-faint">{counts[k]}</span>
102	            </button>
103	          ))}
104	        </span>
105	      </div>
106	
107	      <div className="p-4">
108	        {slice.length === 0 ? (
109	          <p className="py-10 text-center text-[12.5px] text-tx-faint">
110	            {rows.length === 0 ? "Nothing has happened to this server yet." : "Nothing matches that filter."}
111	          </p>
112	        ) : (
113	          <ol className="flex flex-col gap-1.5">
114	            {slice.map((r) => {
115	              const st = STATUS[r.status] ?? { label: r.status, dot: "bg-slate-400", ink: "text-tx-dim" };
116	              const t = TYPE_LABEL[r.type] ?? { label: r.type.replace(/_/g, " ").toLowerCase(), icon: "activity" };
117	              const dur = took(r.createdAt, r.finishedAt);
118	              return (
119	                <li key={r.id} className="flex flex-wrap items-center gap-3 rounded-[11px] border border-rim-soft bg-well px-3.5 py-2.5">
120	                  <span className="grid h-[30px] w-[30px] flex-none place-items-center rounded-[9px] border border-white/10 bg-white/[0.04]">
121	                    <Icon name={t.icon} size={14} tone="inherit" className="text-[#7fb0ff]" />
122	                  </span>
123	                  <span className="flex min-w-[150px] flex-1 flex-col">
124	                    <span className="truncate text-[13px] font-semibold capitalize text-white">{t.label}</span>
125	                    <span className="truncate text-[11.5px] text-tx-faint">
126	                      {when(r.createdAt)}{dur ? ` · took ${dur}` : ""}
127	                    </span>
128	                  </span>
129	                  {r.error && (
130	                    <span className="min-w-0 max-w-[46%] truncate text-[11.5px] text-red-300" title={r.error}>
131	                      {r.error}
132	                    </span>
133	                  )}
134	                  <span className={"flex flex-none items-center gap-2 text-[12px] font-semibold " + st.ink}>
135	                    <span className={"h-[6px] w-[6px] rounded-full " + st.dot} />
136	                    {st.label}
137	                  </span>
138	                </li>
139	              );
140	            })}
141	          </ol>
142	        )}
143	
144	        {pages > 1 && (
145	          <div className="mt-3 flex flex-wrap items-center gap-2.5">
146	            <p className="text-[12px] text-tx-faint">Page {current} of {pages} · {shown.length} entries</p>
147	            <span className="ml-auto flex items-center gap-1.5">
148	              <button type="button" disabled={current <= 1} onClick={() => setPage(current - 1)}
149	                      className="rounded-[9px] border border-rim-hi px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:text-white disabled:opacity-35">
150	                Previous
151	              </button>
152	              <button type="button" disabled={current >= pages} onClick={() => setPage(current + 1)}
153	                      className="rounded-[9px] border border-rim-hi px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:text-white disabled:opacity-35">
154	                Next
155	              </button>
156	            </span>
157	          </div>
158	        )}
159	      </div>
160	    </section>
161	  );
162	}
