1	"use client";
2	
3	import { useCallback, useEffect, useState, useTransition } from "react";
4	import {
5	  getGamePlayers, kickPlayer, banPlayer, pardonPlayer,
6	  listGameOperators, addGameOperator, removeGameOperator,
7	  listGameWhitelist, addGameWhitelist, removeGameWhitelist,
8	  listGameBans, setPlayerGameMode, teleportPlayer,
9	} from "@/lib/actions-game-control";
10	import type { Player } from "@/lib/game-control";
11	
12	const SUB = [
13	  { key: "online", label: "Online" },
14	  { key: "bans", label: "Bans" },
15	  { key: "whitelist", label: "Whitelist" },
16	  { key: "ops", label: "Operators" },
17	] as const;
18	
19	type SubKey = (typeof SUB)[number]["key"];
20	
21	export function GamePlayers({ serverId, running, playersMax }: { serverId: string; running: boolean; playersMax: number | null }) {
22	  const [tab, setTab] = useState<SubKey>("online");
23	
24	  return (
25	    <div className="space-y-5">
26	      <div className="flex flex-wrap gap-1.5">
27	        {SUB.map((s) => {
28	          const active = tab === s.key;
29	          return (
30	            <button
31	              key={s.key}
32	              onClick={() => setTab(s.key)}
33	              className={`rounded-xl px-3.5 py-1.5 text-sm font-medium transition-colors ${
34	                active ? "bg-white/[0.08] text-white ring-1 ring-inset ring-brand-500/40" : "text-slate-400 hover:bg-white/[0.04] hover:text-white"
35	              }`}
36	            >
37	              {s.label}
38	            </button>
39	          );
40	        })}
41	      </div>
42	
43	      {tab === "online" && <OnlinePlayers serverId={serverId} running={running} playersMax={playersMax} />}
44	      {tab === "bans" && <BansPanel serverId={serverId} running={running} />}
