95	
96	  function doTp(name: string) {
97	    const target = prompt(`Teleport ${name} to which player?`);
98	    if (!target?.trim()) return;
99	    setMsg(null);
100	    start(async () => {
101	      const r = await teleportPlayer(serverId, name, target.trim());
102	      if (!r.ok) setErr(r.error); else setMsg(`Teleported ${name} → ${target.trim()}`);
103	    });
104	  }
105	
106	  /* Player listing, kicks and bans all go through RCON, and only three of the
107	     platform's game families speak it. Saying which is better than a flat "not
108	     available" the customer can only read as a fault. */
109	  if (!supported) {
110	    return (
111	      <div className="card">
112	        <h3 className="text-[14px] font-extrabold text-white">No player management for this game</h3>
