114	          Listing, kicking and banning players works over a remote console, and this game doesn&apos;t
115	          expose one. You can still manage players through the game&apos;s own config and whitelist
116	          files in the <strong className="text-slate-200">Files</strong> tab.
117	        </p>
118	      </div>
119	    );
120	  }
121	
122	  return (
123	    <div className="card">
124	      <div className="flex items-center justify-between">
125	        <div>
126	          <h3 className="font-semibold">Connected players</h3>
