128	            {players ? players.length : 0}{playersMax ? ` / ${playersMax}` : ""} online
129	          </p>
130	        </div>
131	        <button className="text-xs text-slate-400 hover:text-white disabled:opacity-40" onClick={refresh} disabled={pending || !running}>Refresh</button>
132	      </div>
133	      {err && <p className="mt-3 text-sm text-amber-300">{err}</p>}
134	      {msg && <p className="mt-2 text-sm text-emerald-400">{msg}</p>}
135	      {!running ? (
136	        <p className="mt-4 text-sm text-slate-500">Start the server to see connected players.</p>
137	      ) : !loaded ? (
138	        <p className="mt-4 text-sm text-slate-500">Loading…</p>
139	      ) : !players || players.length === 0 ? (
140	        <p className="mt-4 text-sm text-slate-500">No players connected.</p>
141	      ) : (
142	        <ul className="mt-4 divide-y divide-white/[0.06]">
143	          {players.map((p) => (
144	            <li key={p.name} className="flex items-center justify-between gap-3 py-2.5">
145	              <span className="flex items-center gap-2.5 text-sm">
