3	import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
4	import { getGameLogs, sendGameCommand } from "@/lib/actions-game-control";
5	import { Icon } from "@/components/nx/Icon";
6	
7	/**
8	 * Console tab — a live terminal over the game process.
9	 *
10	 * Tails logs via getGameLogs (polled), sends console/RCON commands via
11	 * sendGameCommand, and exposes the terminal affordances the card asks for:
12	 * search/filter, clear, auto-scroll toggle, and save/download of the buffer.
13	 *
14	 * Power controls used to be repeated here "for convenience". The hero is pinned
15	 * to every tab and already carries Start/Restart/Stop, so the pair here were a
16	 * second place to press the same button — and were disabled whenever the server
17	 * was stopped, which is exactly when Start is wanted.
18	 */
19	
20	type Line = { text: string; kind: "log" | "cmd" | "out" | "err" };
21	
22	export function GameConsole({ serverId, running }: { serverId: string; running: boolean }) {
23	  const [logLines, setLogLines] = useState<string[]>([]);
24	  const [feed, setFeed] = useState<Line[]>([]);
25	  const [logErr, setLogErr] = useState<string | null>(null);
26	  const [query, setQuery] = useState("");
27	  const [autoScroll, setAutoScroll] = useState(true);
28	  const [rconSupported, setRconSupported] = useState(true);
29	  const [cmd, setCmd] = useState("");
30	  const [msg, setMsg] = useState<string | null>(null);
31	  const [sending, startSend] = useTransition();
32	  const box = useRef<HTMLDivElement>(null);
33	
34	  const refresh = useCallback(() => {
35	    getGameLogs(serverId).then((r) => {
36	      if (r.ok) {
37	        setLogLines(r.lines);
38	        setLogErr(null);
39	      } else {
40	        setLogErr(r.error);
41	        // The action reports when RCON/console isn't available for the family.
42	        if (/not available|no remote console|disabled/i.test(r.error)) setRconSupported(false);
43	      }
44	    });
45	  }, [serverId]);
46	
47	  useEffect(() => {
48	    if (!running) return;
49	    refresh();
50	    const t = setInterval(refresh, 6000);
51	    return () => clearInterval(t);
52	  }, [running, refresh]);
53	
54	  // Merge the tailed log with the interactive command feed into one stream.
55	  const merged: Line[] = useMemo(() => {
56	    const base: Line[] = logLines.map((text) => ({ text, kind: "log" as const }));
57	    return [...base, ...feed];
58	  }, [logLines, feed]);
59	
60	  const filtered = useMemo(() => {
61	    const q = query.trim().toLowerCase();
62	    if (!q) return merged;
63	    return merged.filter((l) => l.text.toLowerCase().includes(q));
64	  }, [merged, query]);
65	
66	  useEffect(() => {
67	    if (autoScroll && box.current) box.current.scrollTop = box.current.scrollHeight;
68	  }, [filtered, autoScroll]);
69	
70	  function send() {
71	    const c = cmd.trim();
72	    if (!c) return;
73	    setFeed((f) => [...f, { text: `> ${c}`, kind: "cmd" }]);
74	    setCmd("");
75	    startSend(async () => {
76	      const r = await sendGameCommand(serverId, c);
77	      setFeed((f) => [
78	        ...f,
79	        r.ok ? { text: r.response || "(no output)", kind: "out" } : { text: `! ${r.error}`, kind: "err" },
80	      ]);
81	    });
82	  }
83	
84	
85	
86	  function download() {
87	    const blob = new Blob([merged.map((l) => l.text).join("\n")], { type: "text/plain" });
88	    const url = URL.createObjectURL(blob);
89	    const a = document.createElement("a");
90	    a.href = url;
91	    a.download = `console-${serverId}-${new Date().toISOString().slice(0, 19).replace(/[:T]/g, "-")}.log`;
92	    a.click();
93	    URL.revokeObjectURL(url);
94	  }
95	
96	  /* Power controls are NOT repeated here. The hero above is pinned to every
97	     tab and already carries Start/Restart/Stop, so a second set one card down
98	     was two places to press the same button — and the pair here were disabled
99	     whenever the server was stopped, which is exactly when Start is wanted. */
100	  return (
101	    <div className="flex flex-col gap-3">
102	      <section className="nx-dark-island flex min-w-0 flex-col overflow-hidden rounded-[16px] border border-rim-hi bg-[rgba(3,9,24,.88)]">
103	        <div className="flex flex-wrap items-center gap-2.5 border-b border-rim-soft px-4 py-2.5">
104	          <h3 className="text-[13.5px] font-extrabold text-white">Live console</h3>
105	          {running && (
106	            <span className="flex items-center gap-1.5 text-[11.5px] font-semibold text-emerald-400">
107	              <span className="h-[6px] w-[6px] animate-pulse rounded-full bg-emerald-400" />
108	              Tailing
109	            </span>
110	          )}
111	
112	          <span className="ml-auto flex h-[32px] w-[180px] items-center gap-2 rounded-[9px] border border-rim-hi bg-well px-3">
113	            <Icon name="search" size={13} tone="inherit" className="flex-none text-tx-faint" />
114	            <input
115	              value={query}
116	              onChange={(e) => setQuery(e.target.value)}
117	              placeholder="Filter…"
118	              className="min-w-0 flex-1 bg-transparent text-[12px] text-white outline-none placeholder:text-tx-faint"
119	            />
120	          </span>
121	          <button
122	            type="button"
123	            onClick={() => setAutoScroll((v) => !v)}
124	            aria-pressed={autoScroll}
125	            className={"rounded-[9px] border px-3 py-1.5 text-[12px] font-semibold transition " +
126	              (autoScroll ? "border-[#8b5cff]/60 bg-[#7b3fef]/20 text-white" : "border-rim-hi text-tx-dim hover:text-white")}
127	          >
128	            Auto-scroll
129	          </button>
130	          <button type="button" onClick={() => { setFeed([]); setLogLines([]); }}
131	                  className="rounded-[9px] border border-rim-hi px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:text-white">
132	            Clear
133	          </button>
134	          <button type="button" onClick={download}
135	                  className="rounded-[9px] border border-rim-hi px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:text-white">
136	            Download
137	          </button>
138	        </div>
139	
