import { db } from "../lib/db";
import { serverRootPassword, connectionTarget, type SftpServer } from "../lib/sftp";
import { Client } from "ssh2";

function run(conn: Client, cmd: string): Promise<{ code: number | null; out: string; err: string }> {
  return new Promise((resolve, reject) => {
    conn.exec(cmd, (err, stream) => {
      if (err) return reject(err);
      let out = "";
      let errOut = "";
      stream
        .on("close", (code: number | null) => resolve({ code, out, err: errOut }))
        .on("data", (d: Buffer) => (out += d.toString("utf8")))
        .stderr.on("data", (d: Buffer) => (errOut += d.toString("utf8")));
    });
  });
}

async function main() {
  const s = await db.server.findUnique({
    where: { id: "cmtsspvu10jf1hlo7x798z354" },
    select: {
      id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true,
      dedicatedIp: { select: { address: true } },
      node: { select: { publicIp: true } },
    },
  });
  if (!s) throw new Error("server not found");

  const target = connectionTarget(s as unknown as SftpServer);
  const password = serverRootPassword(s as unknown as SftpServer);
  if (!target || !password) throw new Error("no connection target or password");

  const conn = new Client();
  await new Promise<void>((resolve, reject) => {
    conn
      .on("ready", () => resolve())
      .on("error", reject)
      .connect({ host: target.host, port: target.port, username: "root", password, readyTimeout: 15000 });
  });

  try {
    console.log("=== systemctl status (valheim units) ===");
    console.log((await run(conn, "systemctl list-units --type=service --all | grep -i valheim || echo NONE")).out);

    console.log("=== journalctl -u valheim (last 48h, last 150 lines) ===");
    const j1 = await run(conn, "journalctl -u valheim --since '48 hours ago' -n 150 --no-pager 2>&1 || echo JOURNAL_FAILED");
    console.log(j1.out || j1.err);

    console.log("=== find likely valheim log files ===");
    const find = await run(conn, "find / -maxdepth 6 -iname '*valheim*log*' -o -iname 'server.log' 2>/dev/null | grep -vi proc | head -40");
    console.log(find.out);

    console.log("=== docker ps (in case it's containerized) ===");
    console.log((await run(conn, "docker ps -a 2>&1 || echo NO_DOCKER")).out);
  } finally {
    conn.end();
  }
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });

